#include <stdio.h>
#include <stdlib.h>

int main()
{
    printf("Programa para calculo de casa \n"); // o \n serve para pular linha
    printf("area da sala e %i \n", 10*10);
    printf("area do quarto e %i \n", 5*7);
    printf("area do banheiro e %i \n", 5*7);
    printf("area total e %i \n", 10*10 + 5*7 + 5*7);

    system("pause");
    return 0;
}